const getLinks = post => {
  const text = post.body.filter(block => typeof block === 'string').join(' ')
  return [...new Set([...text.matchAll(/\[[^\]]+\]\((\/[^)]+)\)/g)].map(match => match[1]))]
}

// Body entries '@image:0' / '@image:1' stand for the post's own two photos.
const withImages = post => ({
  ...post,
  body: post.body.map(block => (typeof block === 'string' && block.startsWith('@image:') ? post.images[Number(block.slice(7))] : block)),
})

export const seoBlogPosts = articleDrafts.map(withImages).map(post => {
  const details = keywordDetails[post.slug]
  const internalLinkOpportunities = getLinks(post)
  return {
    ...post,
    ...details,
    searchIntent: 'Informational, with a transactional play intent',
    internalLinkOpportunities,
    suggestedRelatedArticles: internalLinkOpportunities.filter(path => path.startsWith('/blogs/')),
    schemaRecommendations: ['BlogPosting', 'BreadcrumbList', 'FAQPage for visible questions only'],
    socialTitle: post.title,
    socialDescription: post.metaDescription,
  }
})
